-- API GUARD: every game-object method the pet scripts call must exist in the live ALE (pet-battle/api_manifest.txt, generated by a live probe on the running server).
-- Why: the scripts wrap most calls in pcall, so a wrong name (Emote instead of PerformEmote) fails SILENTLY and the feature just never happens.
-- To refresh after adding a method call: add the name to a probe on the live server (see DEVNOTES "API GUARD") and append "Name=Type" here.
local known = {}
for l in io.lines("pet-battle/api_manifest.txt") do local n = l:match("^(%w+)="); if n then known[n] = true end end
local fails, n = 0, 0
for _, f in ipairs({ "pb_battle", "pb_cast", "pb_store", "pb_wild", "acore_prime", "pb_fxlab" }) do
    local h = io.open((f == "pb_fxlab" and "pet-battle/lab/" or "scripts/") .. f .. ".lua"); if h then
        local src = h:read("*a"); h:close(); local seen = {}
        for name in src:gmatch(":([A-Z]%w+)%(") do
            if not seen[name] then seen[name] = true; n = n + 1
                if not known[name] then fails = fails + 1; print("FAIL scripts/" .. f .. ".lua calls :" .. name .. "() which is not in the live API manifest (a typo fails silently inside pcall)") end
            end
        end
    end
end
print(string.format("api: %d method names checked, %d unknown", n, fails)); os.exit(fails == 0 and 0 or 1)
